probe:
package CorsairProbe;
use strict;
use warnings;
use Cwd qw(getcwd);
use File::Find::Rule;
use File::Temp qw(tempdir);

our $CONTROL_PAYLOAD = 'ordinary-note.txt';
our $EXPLOIT_PAYLOAD = '|printf corsair > owned_marker';

sub run_target {
    my ($payload) = @_;
    my $root = tempdir('corsair-XXXXXX', TMPDIR => 1, CLEANUP => 1);
    my $old = getcwd();
    chdir $root or die "cannot enter owned directory: $!";
    my $invariant;
    my $completed = eval {
        open my $handle, '>', $payload or die "cannot create owned fixture: $!";
        print {$handle} "owned needle\n" if $payload eq $CONTROL_PAYLOAD;
        close $handle or die "cannot close owned fixture: $!";
        if ($payload eq $CONTROL_PAYLOAD) {
            my @found = File::Find::Rule->file->grep(qr/owned needle/)->in('.');
            $invariant = scalar grep { $_ eq $payload || $_ eq "./$payload" } @found;
        } else {
            File::Find::Rule->file->grep(qr/cannot-match/)->in('.');
            $invariant = !-f 'owned_marker';
        }
        1;
    };
    my $error = $@;
    chdir $old or die "cannot restore directory: $!";
    die $error unless $completed;
    return $invariant ? 1 : 0;
}

1;
